var $=function(s,r){return (r||document).querySelector(s)},$$=function(s,r){return Array.from((r||document).querySelectorAll(s))};
function h(s){var d=document.createElement('div');d.innerHTML=s.trim();return d.firstChild}
/* ---------- theme ---------- */
(function(){if(localStorage.getItem('theme')==='light')document.body&&document.body.classList.add('light')})();
document.addEventListener('DOMContentLoaded',function(){if(localStorage.getItem('theme')==='light')document.body.classList.add('light');if(localStorage.getItem('kid')==='1')document.body.classList.add('kid')});
function toggleTheme(){var l=document.body.classList.toggle('light');localStorage.setItem('theme',l?'light':'dark');toast(l?'Light mode':'Dark mode');}
/* ---------- ui helpers ---------- */
function toast(m){var t=h('<div class="toast">'+m+'</div>');document.body.appendChild(t);setTimeout(function(){t.remove()},2000)}
function modal(title,body,actions){var bg=h('<div class="modal-bg"><div class="modal"><div class="row"><h2 class="sp">'+title+'</h2><button class="btn ghost" data-x>✕</button></div><div class="mb">'+body+'</div><div class="row" style="justify-content:flex-end;margin-top:14px" data-acts></div></div></div>');
 (actions||[{t:'Close'}]).forEach(function(a){var b=h('<button class="btn '+(a.pri?'pri':'')+'">'+a.t+'</button>');b.onclick=function(){if(a.fn)a.fn(bg);bg.remove()};$('[data-acts]',bg).appendChild(b)});
 bg.onclick=function(e){if(e.target===bg||e.target.hasAttribute('data-x'))bg.remove()};document.body.appendChild(bg);wire(bg);return bg}
var _drawer;function drawer(title,body){if(!_drawer){_drawer=h('<div class="drawer"></div>');document.body.appendChild(_drawer)}
 _drawer.innerHTML='<div class="row"><h2 class="sp">'+title+'</h2><button class="btn ghost" onclick="closeDrawer()">✕</button></div>'+body;wire(_drawer);requestAnimationFrame(function(){_drawer.classList.add('open')})}
function closeDrawer(){_drawer&&_drawer.classList.remove('open')}
function popMenu(anchor,items){$$('.menu').forEach(function(m){m.remove()});var r=anchor.getBoundingClientRect();var m=h('<div class="menu"></div>');
 items.forEach(function(it){var b=h('<button>'+it.t+'</button>');b.onclick=function(){m.remove();it.fn&&it.fn()};m.appendChild(b)});
 m.style.top=(r.bottom+window.scrollY+4)+'px';m.style.left=Math.max(6,Math.min(r.left,innerWidth-220))+'px';document.body.appendChild(m);
 setTimeout(function(){document.addEventListener('click',function c(e){if(!m.contains(e.target)){m.remove();document.removeEventListener('click',c)}})},0)}
function wire(root){$$('[data-tabs]',root).forEach(function(t){if(t._w)return;t._w=1;var btns=$$('button',t);btns.forEach(function(b){b.onclick=function(){btns.forEach(function(x){x.classList.toggle('on',x===b)});var p=t.parentNode;$$(':scope > .tabpane',p).forEach(function(pn){pn.classList.toggle('on',pn.dataset.pane===b.dataset.t)})}})});
 $$('canvas[data-mol]',root).forEach(function(c){if(!c._v)c._v=new MolViewer(c,c.dataset.mol)});
 $$('svg[data-graph]',root).forEach(function(s){if(!s._g){s._g=1;drawGraph(s,s.dataset.graph)}});
 $$('svg[data-growth]',root).forEach(function(s){if(!s._g){s._g=1;drawGrowth(s)}});
 $$('[data-quiz]',root).forEach(function(q){if(!q._q){q._q=1;runQuiz(q)}});
 $$('[data-chat]',root).forEach(function(q){if(!q._q){q._q=1;runChat(q)}});}
