 c.addEventListener('pointerup',function(){dn=null});c.addEventListener('wheel',function(e){e.preventDefault();s.zoom=Math.max(.4,Math.min(3,s.zoom*(e.deltaY<0?1.1:.9)));s.draw()},{passive:false});
