MolViewer.prototype.set=function(k){this.key=k;var a=MOLS[k].a;this.atoms=a;this.bonds=[];for(var i=0;i<a.length;i++)for(var j=i+1;j<a.length;j++){var d=Math.hypot(a[i][1]-a[j][1],a[i][2]-a[j][2],a[i][3]-a[j][3]);var lim=(a[i][0]==='H'||a[j][0]==='H')?1.2:1.7;if(d<lim&&!(a[i][0]==='H'&&a[j][0]==='H'))this.bonds.push([i,j,(k==='ethanal'&&a[i][0]==='C'&&a[j][0]==='O')?2:1])}this.draw();var ov=this.c.parentNode.querySelector('.ov');if(ov)ov.textContent=MOLS[k].name+' · '+MOLS[k].f+' · drag to rotate'};
MolViewer.prototype.draw=function(){var c=this.c,W=c.clientWidth||300,H=c.clientHeight||240,dpr=devicePixelRatio||1;if(c.width!==W*dpr){c.width=W*dpr;c.height=H*dpr}var g=c.getContext('2d');g.setTransform(dpr,0,0,dpr,0,0);g.clearRect(0,0,W,H);
 var cy=Math.cos(this.ry),sy=Math.sin(this.ry),cx=Math.cos(this.rx),sx=Math.sin(this.rx),sc=Math.min(W,H)/6*this.zoom,s=this;
 var P=this.atoms.map(function(a,i){var x=a[1]*cy+a[3]*sy,z=-a[1]*sy+a[3]*cy,y=a[2]*cx-z*sx;z=a[2]*sx+z*cx;var p=3/(3+z*.25);return{i:i,e:a[0],x:W/2+x*sc*p,y:H/2-y*sc*p,z:z,p:p}});
 var fill=s.style==='space'?1.9:1;
 if(s.style!=='space'){g.lineCap='round';this.bonds.forEach(function(b){var A=P[b[0]],B=P[b[1]];g.strokeStyle=document.body.classList.contains('light')?'#666':'#aab4bf';g.lineWidth=(s.style==='stick'?8:5)*A.p;
  if(b[2]===2){var dx=B.y-A.y,dy=A.x-B.x,l=Math.hypot(dx,dy)||1;dx=dx/l*4;dy=dy/l*4;[[dx,dy],[-dx,-dy]].forEach(function(o){g.beginPath();g.moveTo(A.x+o[0],A.y+o[1]);g.lineTo(B.x+o[0],B.y+o[1]);g.stroke()})}else{g.beginPath();g.moveTo(A.x,A.y);g.lineTo(B.x,B.y);g.stroke()}})}
 P.slice().sort(function(a,b){return a.z-b.z}).forEach(function(a){var r=ARAD[a.e]*sc*.45*a.p*fill;if(s.style==='stick')r=a.e==='H'?4:6;var gr=g.createRadialGradient(a.x-r*.35,a.y-r*.35,r*.1,a.x,a.y,r);gr.addColorStop(0,'#fff');gr.addColorStop(.25,ACOL[a.e]);gr.addColorStop(1,'#111');g.fillStyle=gr;g.beginPath();g.arc(a.x,a.y,r,0,7);g.fill();
  if(s.labels){g.fillStyle=a.e==='H'?'#000':'#fff';g.font='bold 12px system-ui';g.textAlign='center';g.textBaseline='middle';g.fillText(a.e,a.x,a.y)}});
 if(s.hb&&this.key==='ethanol'){g.setLineDash([4,4]);g.strokeStyle='#58a6ff';g.lineWidth=2;var o=P[3];g.beginPath();g.moveTo(o.x,o.y);g.lineTo(o.x-60,o.y-30);g.stroke();g.setLineDash([]);g.fillStyle='#58a6ff';g.font='12px system-ui';g.fillText('H-bond →',o.x-70,o.y-38)}};
